function checks(){$('il').innerHTML=CUR.items.map(function(it,i){var si=it.show_if?Object.keys(it.show_if).map(function(k){return k+'='+(it.show_if[k]||[]).join('|');}).join(';'):'';
 return '<div class="row ir"><input class="id" value="'+E(it.id)+'" aria-label="No."><div class="col"><input class="sx" placeholder="Section heading (optional)" value="'+E(it.section||'')+'"><textarea class="tx" rows="2" placeholder="Check">'+E(it.text)+'</textarea><input class="si" placeholder="Show only when (optional)" value="'+E(si)+'"></div><div class="mv"><button data-up="'+i+'" title="Move up">\u2191</button><button data-dn="'+i+'" title="Move down">\u2193</button><button class="x" data-ix="'+i+'" title="Remove">\u00d7</button></div></div>';}).join('');
