function grab(){CUR.title=S($('t_title').value);CUR.doc_ref=S($('t_ref').value);CUR.review_on=$('t_rev').value;CUR.status=$('t_st').value;CUR.intro=S($('t_in').value);CUR.footer=S($('t_ft').value);CUR.refs=S($('t_rf').value);
 CUR.header=Array.prototype.map.call(document.querySelectorAll('.hfr'),function(r,i){var prev=(CUR.header[i]||{});var o={k:S(r.querySelector('.k').value).replace(/[^a-z0-9_]/gi,'').toLowerCase(),l:S(r.querySelector('.l').value),t:r.querySelector('.t').value};var op=S(r.querySelector('.o').value);if(o.t==='select')o.o=op.split('|').map(S).filter(Boolean);if(r.querySelector('.r').checked)o.req=true;if(prev.allow_hire)o.allow_hire=true;return o;});
 CUR.items=Array.prototype.map.call(document.querySelectorAll('.ir'),function(r){var o={id:S(r.querySelector('.id').value),text:S(r.querySelector('.tx').value)};var sx=S(r.querySelector('.sx').value);if(sx)o.section=sx;var si=S(r.querySelector('.si').value);
  if(si){o.show_if={};si.split(';').forEach(function(p){var kv=p.split('=');if(kv.length===2&&S(kv[0]))o.show_if[S(kv[0])]=kv[1].split('|').map(S).filter(Boolean);});if(!Object.keys(o.show_if).length)delete o.show_if;}return o;});}
function save(){if(BUSY)return;grab();var m=$('msg');
 if(!CUR.title){m.textContent='Give the template a title.';return;}if(!CUR.items.filter(function(i){return i.text;}).length){m.textContent='Add at least one check.';return;}
 var ids={},dupe='';CUR.items.forEach(function(i){if(ids[i.id])dupe=i.id;ids[i.id]=1;});if(dupe){m.textContent='Check number '+dupe+' is used twice.';return;}
 if(CUR.header.some(function(f){return !f.k||!f.l;})){m.textContent='Every header field needs a key and a label.';return;}
 var by=S(prompt('Your name:',me()));if(!by)return;try{localStorage.setItem('cbs_name',by);}catch(x){}
 BUSY=true;$('sv').disabled=true;m.textContent='Saving\u2026';
 fetch('/webhook/cbs-form-templates-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({t:CUR,by:by,note:S($('t_note').value)})}).then(function(r){return r.json();}).then(function(r){
  if(!r||!r.ok){BUSY=false;$('sv').disabled=false;m.textContent=(r&&r.message)||'Could not save.';return;}location.reload();}).catch(function(){BUSY=false;$('sv').disabled=false;m.textContent='Could not save. Try again.';});}
list();}
