/* POST cbs-form-templates-save {t,by,note}: validate, bump the version when the checks or header fields change, keep a history. */
const S=v=>v==null?'':String(v).trim();const b=$('POST cbs-form-templates-save').first().json.body||{};const t=b.t||{};
const by=S(b.by).slice(0,80);if(!by)return [{json:{ok:false,message:'Enter your name.'}}];
const ALL=$input.all().map(i=>i.json).filter(r=>r&&r.id);
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
const T=['text','date','select','asset','sub'];
const header=(Array.isArray(t.header)?t.header:[]).slice(0,20).map(f=>{const o={k:S(f.k).replace(/[^a-z0-9_]/gi,'').toLowerCase().slice(0,30),l:S(f.l).slice(0,80),t:T.indexOf(S(f.t))>-1?S(f.t):'text'};if(o.t==='select')o.o=(Array.isArray(f.o)?f.o:[]).map(x=>S(x).slice(0,60)).filter(Boolean).slice(0,30);if(f.req)o.req=true;if(f.allow_hire)o.allow_hire=true;return o;}).filter(f=>f.k&&f.l);
const items=(Array.isArray(t.items)?t.items:[]).slice(0,120).map(i=>{const o={id:S(i.id).slice(0,8),text:S(i.text).slice(0,300)};if(S(i.section))o.section=S(i.section).slice(0,80);
 if(i.show_if&&typeof i.show_if==='object'){const si={};Object.keys(i.show_if).slice(0,3).forEach(k=>{const v=(Array.isArray(i.show_if[k])?i.show_if[k]:[]).map(x=>S(x)).filter(Boolean);if(v.length)si[S(k).toLowerCase()]=v;});if(Object.keys(si).length)o.show_if=si;}return o;}).filter(i=>i.id&&i.text);
if(!S(t.title))return [{json:{ok:false,message:'Give the template a title.'}}];if(!items.length)return [{json:{ok:false,message:'Add at least one check.'}}];
const ex=Number(t.id)>0?ALL.find(r=>Number(r.id)===Number(t.id)):null;
if(Number(t.id)>0&&!ex)return [{json:{ok:false,message:'Template not found. Refresh the page.'}}];
const hj=JSON.stringify(header),ij=JSON.stringify(items);
let version='1.0';if(ex){version=S(ex.version)||'1.0';const ch=hj!==S(ex.header_json)||ij!==S(ex.items_json)||S(t.intro)!==S(ex.intro)||S(t.footer)!==S(ex.footer);
 if(ch){const p=version.split('.');version=(Number(p[0])||1)+'.'+((Number(p[1])||0)+1);}}
let hist=[];try{hist=JSON.parse(S(ex&&ex.history)||'[]')||[];}catch(e){}hist.push({at:now,by:by,v:version,note:S(b.note).slice(0,200)||(ex?'Edited':'Created')});
let tkey=ex?S(ex.tkey):S(t.title).toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,30)||'form';
if(!ex){let k=tkey,n=2;while(ALL.some(r=>S(r.tkey)===k))k=tkey+'_'+(n++);tkey=k;}
const row={tkey:tkey,kind:ex?S(ex.kind):'preuse',title:S(t.title).slice(0,120),doc_ref:S(t.doc_ref).slice(0,30),version:version,prepared_on:ex&&version===S(ex.version)?S(ex.prepared_on):now.slice(0,10),
 review_on:/^\d{4}-\d\d-\d\d$/.test(S(t.review_on))?S(t.review_on):(ex?S(ex.review_on):''),status:S(t.status)==='Retired'?'Retired':'Active',header_json:hj,items_json:ij,
 intro:S(t.intro).slice(0,1000),footer:S(t.footer).slice(0,2000),refs:S(t.refs).slice(0,300),sort:ex?Number(ex.sort)||0:ALL.length+1,updated_by:by,updated_at:now,history:JSON.stringify(hist.slice(-50))};
return [{json:{ok:true,is_new:!ex,id:ex?ex.id:0,version:version,row:row}}];

/* Form Prefill: fills Task / RAMS ref from the job's current RAMS, and the HAV
   box from the tool the user picks. Only ever fills an empty box. Injected here
   so the very large Forms Page node is left alone. */
