fetch('/webhook/cbs-forms-data?job='+encodeURIComponent(C.job||''),{cache:'no-store'})
.then(function(r){return r.json();}).then(function(d){d=d||{};
 var ref=((d.job)||{}).rams_ref||'',AS=d.assets||[];
 function put(id,v){var e=document.getElementById(id);if(!e)return false;if(v&&!String(e.value||'').trim()){e.value=v;try{e.dispatchEvent(new Event('change'));}catch(x){}}return true;}
 function hook(){var s=document.getElementById('h_asset');if(!s)return false;if(s.dataset.havhook)return true;s.dataset.havhook='1';
  s.addEventListener('change',function(){var a=AS.filter(function(x){return String(x.id)===String(s.value);})[0];if(!a)return;
   var bits=[a.hav_ref,a.hav_mins?('trigger '+a.hav_mins+' min'):'',a.hav_mag?(a.hav_mag+' m/s2'):''].filter(Boolean).join(' · ');
   put('h_hav',bits);});return true;}
 (function w(){var a=!ref||put('h_rams',ref),b=hook();if((a&&b)||n++>=120)return;setTimeout(w,250);})();
}).catch(function(){});};
